context_present = knowledge_check_all is not None

states = {((1, 2, 3), 4): 1.0}
hit_probability = {n: 0.0 for n in range(1, 101)}

while states:
    next_states = {}
    for (platform, next_ball), mass in states.items():
        branch = mass / 3.0
        for pos in range(3):
            hit_probability[platform[pos]] += branch

            if pos == 0:
                remaining = [platform[1], platform[2]]
                needed = 1
            elif pos == 1:
                remaining = [platform[2]]
                needed = 2
            else:
                remaining = [platform[1]]
                needed = 2

            available = max(0, 101 - next_ball)
            take = min(needed, available)
            updated = tuple(remaining + list(range(next_ball, next_ball + take)))
            updated_next = next_ball + take

            if updated_next <= 100:
                key = (updated, updated_next)
                next_states[key] = next_states.get(key, 0.0) + branch
            else:
                # Once the ramp is empty, every ball still on the platform
                # will eventually be struck; this branch contributes fully.
                for ball in updated:
                    hit_probability[ball] += branch

    states = next_states

maximum = max(hit_probability.values())
best_balls = [ball for ball, probability in hit_probability.items()
              if abs(probability - maximum) < 1e-12]
computed_answer = {
    "best_balls": best_balls,
    "maximum_probability": maximum,
    "probability_sum": sum(hit_probability.values()),
    "context_used": context_present
}
print(computed_answer)
